"use client";

/**
 * Light sweep: a soft diagonal band of light crosses the surface once every
 * few seconds, like a reflection sliding over glass. Use it under a logo or a
 * hero title to give a still frame a pulse.
 *
 * Written by Better Design. The sweep repeats every `every` frames, so a
 * composition that length loops without a seam.
 */
import type { ReactNode } from "react";
import { AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

export interface LightSweepProps {
  /** Drawn under the light, so the sweep passes over it too. */
  children?: ReactNode;
  /** Frames between the start of one sweep and the next. */
  every?: number;
  /** Frames one sweep takes to cross the frame. */
  sweepFrames?: number;
  /** Angle of the band, in degrees from vertical. */
  angle?: number;
  /** Width of the band, as a share of the frame width. */
  bandWidth?: number;
  /** Brightness of the band, 0 to 1. */
  intensity?: number;
  /** Frame the first sweep starts on. */
  delay?: number;
  theme?: Partial<VideoTheme>;
}

/** A soft diagonal band of light that sweeps the surface every `every` frames, children underneath. */
export function LightSweep({ children, every = 120, sweepFrames = 56, angle = 20, bandWidth = 0.32, intensity = 0.6, delay = 20, theme: themeOverride }: LightSweepProps) {
  const t = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const local = (((frame - delay) % every) + every) % every;
  const p = easings.inOut(interpolate(local, [0, sweepFrames], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
  const active = local < sweepFrames;

  // The band is wider than the frame's diagonal so its angled edges never show.
  const bandPx = width * bandWidth;
  const x = interpolate(p, [0, 1], [-bandPx * 1.5, width + bandPx * 0.5]);
  // A primary-tinted halo carries the band on a light page; a white core lights it on a dark one.
  const glow = t.primary;
  const core = "oklch(1 0 0)";
  const surface = `linear-gradient(160deg, ${withAlpha(t.primary, 0)} 30%, ${withAlpha(t.primary, 0.06)} 100%), ${t.background}`;

  return (
    <AbsoluteFill style={{ background: surface, overflow: "hidden" }}>
      {children ? <AbsoluteFill>{children}</AbsoluteFill> : null}
      {active ? (
        <div
          style={{
            position: "absolute",
            top: -height * 0.4,
            bottom: -height * 0.4,
            left: x,
            width: bandPx,
            transform: `rotate(${angle}deg)`,
            background: `linear-gradient(90deg, ${withAlpha(glow, 0)} 0%, ${withAlpha(glow, intensity * 0.16)} 32%, ${withAlpha(core, intensity * 0.55)} 50%, ${withAlpha(glow, intensity * 0.16)} 68%, ${withAlpha(glow, 0)} 100%)`,
            filter: "blur(24px)",
          }}
        />
      ) : null}
    </AbsoluteFill>
  );
}
